#include <stdio.h>

int bowl = 0;

void put_in(int n) {
    bowl = bowl + n;
}

void eat_one(void) {
    bowl = bowl - 1;
}

int peek(void) {
    return bowl;
}

int main(void) {
    put_in({a});
    printf("放进 {a} 条，碗里 %d 条\n", peek());
    eat_one();
    eat_one();
    printf("吃掉 2 条，碗里 %d 条\n", peek());
    put_in({b});
    printf("再放进 {b} 条，碗里 %d 条\n", peek());
    return 0;
}
